import sys

def main():
    data = sys.stdin.read().split()
    n, m, k = int(data[0]), int(data[1]), int(data[2])
    W = m + 1
    P = [0] * ((n + 1) * W)
    pos = 3
    for i in range(n):
        run = 0
        base = (i + 1) * W
        up = i * W
        for j in range(m):
            run += int(data[pos])
            pos += 1
            P[base + j + 1] = P[up + j + 1] + run
    found = False
    for d in range(-(n - 1), m):
        i0 = 0 if d >= 0 else -d
        j0 = d if d >= 0 else 0
        L = min(n - i0, m - j0)
        r = 0
        for l in range(L):
            if r < l:
                r = l
            while r < L:
                s = P[(i0 + r + 1) * W + j0 + r + 1] - P[(i0 + l) * W + j0 + r + 1] - P[(i0 + r + 1) * W + j0 + l] + P[(i0 + l) * W + j0 + l]
                if s < k:
                    r += 1
                else:
                    break
            if r >= L:
                break
            if s == k:
                found = True
                break
        if found:
            break
    print('YES' if found else 'NO')

main()

